@import "@fontsource-variable/montserrat";

/* Light (the faithful mode): white and warm paper bands, warm ink text, an acid-green brand
   colour and a blush pink for the second voice. */
:root {
  --background: #ffffff;
  --foreground: #171313;
  --card: #ffffff;
  --card-foreground: #171313;
  --popover: #ffffff;
  --popover-foreground: #171313;
  --primary: #c8ff12;
  --primary-foreground: #171313;
  /* stone: the footer band */
  --secondary: #b2aead;
  --secondary-foreground: #171313;
  /* paper: the quiet bands and icon tiles */
  --muted: #efeae9;
  --muted-foreground: #514e4e;
  --accent: #efeae9;
  --accent-foreground: #171313;
  --destructive: #d83a3a;
  --destructive-foreground: #ffffff;
  --border: rgb(23 19 19 / 16%);
  --input: rgb(23 19 19 / 25%);
  --ring: #a6d600;
  /* blush: the user's chat bubbles, hero glow, small round icons */
  --highlight: #ffc7d8;
  --highlight-foreground: #171313;
  --glow: #c8ff12;
  --chart-1: #c8ff12;
  --chart-2: #ffc7d8;
  --chart-3: #171313;
  --chart-4: #b2aead;
  --chart-5: #7a9c00;
  --sidebar: #efeae9;
  --sidebar-foreground: #171313;
  --sidebar-primary: #171313;
  --sidebar-primary-foreground: #ffffff;
  --sidebar-accent: #ffffff;
  --sidebar-accent-foreground: #171313;
  --sidebar-border: rgb(23 19 19 / 16%);
  --sidebar-ring: #a6d600;

  --typeface-body: "Montserrat Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "Montserrat Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 1.5rem;
  --page-width: 82rem;
  --page-gutter: 1rem;
  --section-y: 4rem;
}

/* Dark (a sibling): the ink becomes the page, cards a warm charcoal, the same acid and blush. */
.dark {
  --background: #171313;
  --foreground: #f7f3f2;
  --card: #221d1d;
  --card-foreground: #f7f3f2;
  --popover: #221d1d;
  --popover-foreground: #f7f3f2;
  --primary: #c8ff12;
  --primary-foreground: #171313;
  --secondary: #2c2626;
  --secondary-foreground: #f7f3f2;
  --muted: #1e1919;
  --muted-foreground: #bdb6b5;
  --accent: #2c2626;
  --accent-foreground: #f7f3f2;
  --destructive: #ef5b5b;
  --destructive-foreground: #171313;
  --border: rgb(255 255 255 / 13%);
  --input: rgb(255 255 255 / 22%);
  --ring: #c8ff12;
  --highlight: #ffc7d8;
  --highlight-foreground: #171313;
  --glow: #c8ff12;
  --chart-1: #c8ff12;
  --chart-2: #ffc7d8;
  --chart-3: #f7f3f2;
  --chart-4: #8a8483;
  --chart-5: #9ccc00;
  --sidebar: #1e1919;
  --sidebar-foreground: #f7f3f2;
  --sidebar-primary: #c8ff12;
  --sidebar-primary-foreground: #171313;
  --sidebar-accent: #2c2626;
  --sidebar-accent-foreground: #f7f3f2;
  --sidebar-border: rgb(255 255 255 / 13%);
  --sidebar-ring: #c8ff12;
}
